insert into public.eval_case (id, golden_set_version, stage, source, curriculum, subject, input, draft_labels, needs_human_label, traps)
values
  ('82403068-5862-5726-b199-d7e5c6bb1eec', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "1(a)", "marks_available": 3, "question_text": "Express 2x^2 - 12x + 7 in the form a(x + b)^2 + c, where a, b and c are constants. Hence state the coordinates of the minimum point of y = 2x^2 - 12x + 7.", "student_answer": "2(x-3)^2 - 11, min point (3, -11)", "expected": {"primary": ["1.1.1"], "also_ok": ["1.3.5"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.1.1"], "also_ok": ["1.3.5"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('b50c95b3-9845-517a-a3e1-3bb54fe46528', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "4", "marks_available": 5, "question_text": "Find the set of values of k for which the line y = kx - 3 does not meet the curve y = x^2 + 2x + 1.", "student_answer": "x^2 + (2-k)x + 4 = 0, b^2 - 4ac < 0, (2-k)^2 < 16, -2 < k < 6", "expected": {"primary": ["1.1.2"], "also_ok": ["1.1.3", "1.1.4", "1.3.4"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.1.2"], "also_ok": ["1.1.3", "1.1.4", "1.3.4"], "control": null}, "draft": true}'::jsonb, true, array['shares words with straight lines; the marks are for the discriminant']::text[]),
  ('15b017ca-7661-5976-ab6c-8312cdb98438', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "6", "marks_available": 4, "question_text": "The diagram shows a sector OAB of a circle with centre O and radius 8 cm. The angle AOB is 1.2 radians. Find the perimeter and the area of the sector.", "student_answer": "arc = 9.6, perimeter = 25.6 cm, area = 0.5 x 64 x 1.2 = 38.4 cm^2", "expected": {"primary": ["1.4.2"], "also_ok": ["1.4.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.4.2"], "also_ok": ["1.4.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('ce2a44ed-6e8f-584a-af97-e396fb734df4', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "5", "marks_available": 5, "question_text": "Solve the equation 3 sin^2 θ - 2 cos θ - 2 = 0 for 0° ≤ θ ≤ 360°.", "student_answer": "3(1 - cos^2 θ) - 2cos θ - 2 = 0, 3cos^2 θ + 2cos θ - 1 = 0, cos θ = 1/3 or -1, θ = 70.5°, 180°, 289.5°", "expected": {"primary": ["1.5.5", "1.5.4"], "also_ok": ["1.5.4", "1.5.5", "1.1.5", "2.3.2", "3.3.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.5.5", "1.5.4"], "also_ok": ["1.5.4", "1.5.5", "1.1.5", "2.3.2", "3.3.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('1561f3e3-b5e6-5bbf-a123-1c541242339c', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "2", "marks_available": 3, "question_text": "Find the coefficient of x^3 in the expansion of (2 - x/2)^7.", "student_answer": "7C3 x 2^4 x (-1/2)^3 = 35 x 16 x -1/8 = -70", "expected": {"primary": ["1.6.1"], "also_ok": [], "control": null}}'::jsonb, '{"expected": {"primary": ["1.6.1"], "also_ok": [], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('0609e850-0999-5849-b84a-2c135521ac91', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "7(b)", "marks_available": 4, "question_text": "The first term of a geometric progression is 24 and the sum to infinity is 96. Find the common ratio and the fourth term.", "student_answer": "24/(1-r) = 96, r = 3/4, fourth term = 24 x (3/4)^3 = 10.125", "expected": {"primary": ["1.6.4"], "also_ok": ["1.6.2", "1.6.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.6.4"], "also_ok": ["1.6.2", "1.6.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('ad7d401b-1150-551e-8dc7-6ebfc214d03f', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "9", "marks_available": 6, "question_text": "The curve y = x^3 - 6x^2 + 9x + 2 has two stationary points. Find their coordinates and determine the nature of each.", "student_answer": "dy/dx = 3x^2 - 12x + 9 = 0, x = 1 or 3, (1, 6) max, (3, 2) min using second derivative", "expected": {"primary": ["1.7.4"], "also_ok": ["1.7.2", "1.7.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.7.4"], "also_ok": ["1.7.2", "1.7.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('af3be3a1-a8c3-57c4-ab09-721ce9ec585f', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "8", "marks_available": 4, "question_text": "Find the area of the region bounded by the curve y = 6x - x^2 and the x-axis.", "student_answer": "integral from 0 to 6 of 6x - x^2 = [3x^2 - x^3/3] = 108 - 72 = 36", "expected": {"primary": ["1.8.4"], "also_ok": ["1.8.1", "1.8.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.8.4"], "also_ok": ["1.8.1", "1.8.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('008222e9-28a9-5862-8fec-c27a73132040', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "3", "marks_available": 4, "question_text": "Use logarithms to solve the equation 5^(2x - 1) = 3^(x + 2), giving x correct to 3 significant figures.", "student_answer": "(2x-1)ln5 = (x+2)ln3, x(2ln5 - ln3) = 2ln3 + ln5, x = 1.62", "expected": {"primary": ["2.2.3", "3.2.3"], "also_ok": ["2.2.1", "3.2.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["2.2.3", "3.2.3"], "also_ok": ["2.2.1", "3.2.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('5e1301f3-12d1-5b67-a466-9f7a0999705a', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "6", "marks_available": 5, "question_text": "Use integration by parts to find the exact value of the integral of x e^(2x) from 0 to 1.", "student_answer": "[x e^(2x)/2] - integral e^(2x)/2 = (e^2 + 1)/4", "expected": {"primary": ["3.5.5"], "also_ok": ["3.5.1", "2.5.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["3.5.5"], "also_ok": ["3.5.1", "2.5.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('39fb637d-180f-5210-8ab0-b01bbc3b2148', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "10(b)", "marks_available": 4, "question_text": "The lines l and m have equations r = i + 2j - k + s(2i - j + 3k) and r = 3i + j + 2k + t(i + j - k). Show that l and m are skew.", "student_answer": "not parallel since direction vectors not multiples; equating components gives inconsistent equations so skew", "expected": {"primary": ["3.7.5"], "also_ok": ["3.7.4"], "control": null}}'::jsonb, '{"expected": {"primary": ["3.7.5"], "also_ok": ["3.7.4"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('a326e383-8869-50f2-9e0e-342cfa37b596', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "5(a)", "marks_available": 3, "question_text": "The masses of apples from an orchard are normally distributed with mean 152 g and standard deviation 11 g. Find the probability that a randomly chosen apple has a mass greater than 170 g.", "student_answer": "z = (170-152)/11 = 1.636, P = 1 - 0.949 = 0.0509", "expected": {"primary": ["5.5.2"], "also_ok": ["5.5.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["5.5.2"], "also_ok": ["5.5.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('13e3053a-f721-5c28-a1fe-684f83aa48ff', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "3", "marks_available": 4, "question_text": "A box of mass 5 kg rests on a rough horizontal floor. The coefficient of friction between the box and the floor is 0.3. A horizontal force of 20 N is applied to the box. Determine whether the box moves, justifying your answer.", "student_answer": "R = 50, max friction = 15 N < 20 N so box moves", "expected": {"primary": ["4.1.6"], "also_ok": ["4.1.1", "4.1.3", "4.1.4", "4.4.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["4.1.6"], "also_ok": ["4.1.1", "4.1.3", "4.1.4", "4.4.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('0e347d3e-d98d-5334-a38d-ee02c05553a5', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "6", "marks_available": 5, "question_text": "A coin is thrown 12 times and shows heads 10 times. Test at the 5% significance level whether the coin is biased towards heads.", "student_answer": "H0 p = 0.5, H1 p > 0.5, P(X ≥ 10) = 0.0193 < 0.05, reject H0, evidence of bias", "expected": {"primary": ["6.5.2"], "also_ok": ["6.5.1", "5.4.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["6.5.2"], "also_ok": ["6.5.1", "5.4.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('607bb843-3942-5f0b-95be-9481170e7850', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "7(ii)", "marks_available": 2, "question_text": "(ii) Hence find the value of k.", "student_answer": "k = 4", "expected": {"primary": [], "also_ok": [], "control": "no_context"}}'::jsonb, '{"expected": {"primary": [], "also_ok": [], "control": "no_context"}, "draft": true}'::jsonb, true, array['a part with no stem cannot be placed; an empty answer beats a guess']::text[]),
  ('7a33dd5c-5d9b-57fd-9b8b-0e23885cb1ac', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Mathematics 9709', '{"syllabus_code": "9709", "label": "2", "marks_available": 3, "question_text": "Describe the role of mitochondria in a eukaryotic cell.", "student_answer": "they release energy by respiration", "expected": {"primary": [], "also_ok": [], "control": "off_syllabus"}}'::jsonb, '{"expected": {"primary": [], "also_ok": [], "control": "off_syllabus"}, "draft": true}'::jsonb, true, array[]::text[]),
  ('e79cedb6-7379-5494-9217-ab37cdf3df89', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "1", "marks_available": 4, "question_text": "The roots of the equation x^3 - 4x^2 + 2x - 7 = 0 are α, β and γ. Find the value of α^2 + β^2 + γ^2.", "student_answer": "Σα = 4, Σαβ = 2, Σα^2 = 16 - 4 = 12", "expected": {"primary": ["1.1.1"], "also_ok": [], "control": null}}'::jsonb, '{"expected": {"primary": ["1.1.1"], "also_ok": [], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('b596123a-8078-57b7-b547-1e0cc47d749c', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "3", "marks_available": 5, "question_text": "Use the method of differences to find the sum of 1/(r(r + 1)) for r = 1 to n, and deduce the sum to infinity.", "student_answer": "1/r - 1/(r+1), sum = 1 - 1/(n+1), sum to infinity = 1", "expected": {"primary": ["1.3.2"], "also_ok": ["1.3.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.3.2"], "also_ok": ["1.3.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('30c2d627-b58e-5caa-9d48-38c9e6a5e775', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "2", "marks_available": 5, "question_text": "Prove by mathematical induction that 7^n - 1 is divisible by 6 for every positive integer n.", "student_answer": "n=1 gives 6; assume 7^k - 1 = 6m; 7^(k+1) - 1 = 7(6m+1) - 1 = 42m + 6", "expected": {"primary": ["1.7.1"], "also_ok": [], "control": null}}'::jsonb, '{"expected": {"primary": ["1.7.1"], "also_ok": [], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('b01defb1-78f3-5d69-992b-3b238653208e', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "5(a)", "marks_available": 5, "question_text": "Find the eigenvalues of the matrix with rows (3, 1) and (2, 2), and a corresponding eigenvector for each eigenvalue.", "student_answer": "λ^2 - 5λ + 4 = 0, λ = 1, 4; eigenvectors (1, -2) and (1, 1)", "expected": {"primary": ["2.2.4"], "also_ok": ["2.2.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["2.2.4"], "also_ok": ["2.2.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('30fafa7f-af57-5155-a7ad-3fbe28aaf5e3', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "6", "marks_available": 6, "question_text": "Use de Moivre''s theorem to express cos 5θ in terms of powers of cos θ.", "student_answer": "Re((c + is)^5) = c^5 - 10c^3 s^2 + 5cs^4, cos5θ = 16c^5 - 20c^3 + 5c", "expected": {"primary": ["2.5.3"], "also_ok": ["2.5.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["2.5.3"], "also_ok": ["2.5.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('6bd67b95-a9c0-5f82-8521-10224096aa7d', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "8", "marks_available": 8, "question_text": "Find the general solution of the differential equation d^2y/dx^2 - 5 dy/dx + 6y = 2x.", "student_answer": "CF A e^(2x) + B e^(3x), PI y = x/3 + 5/18", "expected": {"primary": ["2.6.3", "2.6.4"], "also_ok": ["2.6.2", "2.6.3", "2.6.4"], "control": null}}'::jsonb, '{"expected": {"primary": ["2.6.3", "2.6.4"], "also_ok": ["2.6.2", "2.6.3", "2.6.4"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('7bfe8337-599d-5aa4-89e5-b0005204a6ed', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "1", "marks_available": 4, "question_text": "A particle is projected from a point on horizontal ground with speed 20 m s^-1 at an angle of 30° above the horizontal. Find the greatest height reached by the particle.", "student_answer": "vertical component 10, v^2 = u^2 - 2gs, s = 100/20 = 5 m", "expected": {"primary": ["3.1.2"], "also_ok": ["3.1.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["3.1.2"], "also_ok": ["3.1.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('856b35ea-c223-5d96-9155-8054597e06c2', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "4", "marks_available": 5, "question_text": "Find the Maclaurin series for ln(1 + sin x) up to and including the term in x^2.", "student_answer": "f(0) = 0, f''(0) = 1, f''''(0) = -1, so x - x^2/2", "expected": {"primary": ["2.3.3"], "also_ok": [], "control": null}}'::jsonb, '{"expected": {"primary": ["2.3.3"], "also_ok": [], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('45d046ca-1805-5683-a949-d0b57cbf18a7', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "5", "marks_available": 6, "question_text": "One end of a light inextensible string of length 0.8 m is attached to a fixed point O and a particle of mass 0.2 kg is attached to the other end. The particle moves in a complete vertical circle with speed 5 m s^-1 at its lowest point. Find the tension in the string at the lowest point.", "student_answer": "T - mg = mv^2/r, T = 2 + 0.2 x 25/0.8 = 8.25 N", "expected": {"primary": ["3.3.4"], "also_ok": ["3.3.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["3.3.4"], "also_ok": ["3.3.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('3c12a4d5-da15-5a82-9bd5-a3720ff7c347', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Further Mathematics 9231', '{"syllabus_code": "9231", "label": "4(b)", "marks_available": 3, "question_text": "4 (b) Hence [illegible] the value of [illegible] as n tends to [illegible].", "student_answer": "", "expected": {"primary": [], "also_ok": [], "control": "no_context"}}'::jsonb, '{"expected": {"primary": [], "also_ok": [], "control": "no_context"}, "draft": true}'::jsonb, true, array['unreadable stem: never tag from the surviving words']::text[]),
  ('e879fe61-0812-5b03-ba6e-7f56bb9220ae', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "2(b)", "marks_available": 3, "question_text": "A car accelerates uniformly from 5.0 m s^-1 to 25 m s^-1 in 8.0 s. Calculate the distance travelled by the car in this time.", "student_answer": "s = (u + v)t/2 = 15 x 8 = 120 m", "expected": {"primary": ["2.1.7"], "also_ok": ["2.1.1", "2.1.6"], "control": null}}'::jsonb, '{"expected": {"primary": ["2.1.7"], "also_ok": ["2.1.1", "2.1.6"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('a7e0aeca-2a94-5e19-8b73-ab8bdba861b2', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "3(a)", "marks_available": 2, "question_text": "State the principle of conservation of momentum.", "student_answer": "total momentum of a system stays constant if no resultant external force acts", "expected": {"primary": ["3.3.1"], "also_ok": [], "control": null}}'::jsonb, '{"expected": {"primary": ["3.3.1"], "also_ok": [], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('4bbc2f89-8492-5d12-af30-f5a49703e3ad', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "3(b)", "marks_available": 4, "question_text": "A ball of mass 0.20 kg moving at 6.0 m s^-1 collides head-on with a stationary ball of mass 0.30 kg. After the collision the first ball is at rest. Calculate the speed of the second ball and state, with a reason, whether the collision is elastic.", "student_answer": "1.2 = 0.3v, v = 4.0; KE before 3.6 J, after 2.4 J so inelastic", "expected": {"primary": ["3.3.2"], "also_ok": ["3.3.3", "3.1.3", "5.2.4"], "control": null}}'::jsonb, '{"expected": {"primary": ["3.3.2"], "also_ok": ["3.3.3", "3.1.3", "5.2.4"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('992460e4-3bf0-5168-af22-94b552f792d3', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "4(b)", "marks_available": 3, "question_text": "A uniform beam of length 2.0 m is pivoted at its centre. A weight of 30 N hangs 0.40 m from the pivot. Calculate the distance from the pivot, on the other side, at which a 20 N weight must hang for the beam to balance.", "student_answer": "30 x 0.4 = 20 x d, d = 0.60 m", "expected": {"primary": ["4.2.1"], "also_ok": ["4.1.2", "4.2.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["4.2.1"], "also_ok": ["4.1.2", "4.2.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('71e0e20c-84d1-5e07-b1c3-2034b8285724', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "4(c)", "marks_available": 2, "question_text": "Calculate the increase in pressure at a depth of 12 m below the surface of seawater of density 1030 kg m^-3.", "student_answer": "Δp = ρgΔh = 1030 x 9.81 x 12 = 1.2 x 10^5 Pa", "expected": {"primary": ["4.3.4"], "also_ok": ["4.3.2", "4.3.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["4.3.4"], "also_ok": ["4.3.2", "4.3.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('bc7ad855-ee7a-57e7-b8fd-a05fecf0855f', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "5(a)", "marks_available": 3, "question_text": "A wire of length 2.0 m and cross-sectional area 0.20 mm^2 has a resistance of 3.4 Ω. Calculate the resistivity of the material of the wire.", "student_answer": "ρ = RA/L = 3.4 x 0.2 x 10^-6 / 2 = 3.4 x 10^-7 Ω m", "expected": {"primary": ["9.3.6"], "also_ok": ["9.3.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["9.3.6"], "also_ok": ["9.3.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('c716294f-5a0d-5009-b4d8-92ce1ff26f10', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "6(a)", "marks_available": 3, "question_text": "A 6.0 Ω resistor and a 3.0 Ω resistor are connected in parallel. This combination is connected in series with a 4.0 Ω resistor. Calculate the total resistance.", "student_answer": "parallel 2.0 Ω, total 6.0 Ω", "expected": {"primary": ["10.2.6", "10.2.4"], "also_ok": ["10.2.4", "10.2.6", "10.2.7"], "control": null}}'::jsonb, '{"expected": {"primary": ["10.2.6", "10.2.4"], "also_ok": ["10.2.4", "10.2.6", "10.2.7"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('b759b12c-79c9-5812-aea5-bc65270a8c6b', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "4(a)", "marks_available": 3, "question_text": "Explain why the frequency of the siren heard by a stationary observer is higher than the emitted frequency while the ambulance moves towards the observer.", "student_answer": "the waves get squashed, wavelength shorter so frequency higher", "expected": {"primary": ["7.3.1"], "also_ok": ["7.3.2"], "control": null}}'::jsonb, '{"expected": {"primary": ["7.3.1"], "also_ok": ["7.3.2"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('2bd6d489-7dd8-53dc-a42f-16c00605a785', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "7(b)", "marks_available": 3, "question_text": "Light of wavelength 450 nm is incident on a metal surface of work function 2.3 eV. Calculate the maximum kinetic energy of the emitted electrons.", "student_answer": "E = hc/λ = 4.42 x 10^-19 J, Φ = 3.68 x 10^-19 J, KE max = 7.4 x 10^-20 J", "expected": {"primary": ["22.2.4"], "also_ok": ["22.1.3", "22.1.4", "22.2.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["22.2.4"], "also_ok": ["22.1.3", "22.1.4", "22.2.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('64fbc274-ad9e-55c4-b149-f835d0fa0718', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "8(b)", "marks_available": 4, "question_text": "A radioactive isotope has a half-life of 8.0 days. Calculate its decay constant, in s^-1, and the fraction of the original nuclei remaining after 20 days.", "student_answer": "λ = 0.693/(8 x 86400) = 1.0 x 10^-6 s^-1, fraction = e^(-λt) = 0.18", "expected": {"primary": ["23.2.5", "23.2.6"], "also_ok": ["23.2.3", "23.2.5", "23.2.6"], "control": null}}'::jsonb, '{"expected": {"primary": ["23.2.5", "23.2.6"], "also_ok": ["23.2.3", "23.2.5", "23.2.6"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('40f58785-c6c1-54fb-adfb-cab681cbc5ab', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "6(a)", "marks_available": 2, "question_text": "Two parallel metal plates are 4.0 mm apart and have a potential difference of 600 V between them. Calculate the electric field strength between the plates.", "student_answer": "E = V/d = 600 / 0.004 = 1.5 x 10^5 V m^-1", "expected": {"primary": ["18.2.1"], "also_ok": ["18.1.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["18.2.1"], "also_ok": ["18.1.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
  ('6a0edda8-b5cb-5f2c-af81-035a86bf8968', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Physics 9702', '{"syllabus_code": "9702", "label": "7(c)", "marks_available": 4, "question_text": "A 470 μF capacitor charged to 12 V discharges through a 10 kΩ resistor. Calculate the time constant and the potential difference across the capacitor after 3.0 s.", "student_answer": "τ = RC = 4.7 s, V = 12 e^(-3/4.7) = 6.3 V", "expected": {"primary": ["19.3.2", "19.3.3"], "also_ok": ["19.3.2", "19.3.3", "19.3.1"], "control": null}}'::jsonb, '{"expected": {"primary": ["19.3.2", "19.3.3"], "also_ok": ["19.3.2", "19.3.3", "19.3.1"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
