  ('1c5132ec-5073-513e-9913-c29fd8d5b53e', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Computer Science 9618', '{"syllabus_code": "9618", "label": "3", "marks_available": 4, "question_text": "Explain the difference between lossy and lossless compression. Give one situation in which each would be the better choice.", "student_answer": "lossy removes data permanently e.g. streaming video; lossless keeps all data e.g. text files", "expected": {"primary": ["1.3.2"], "also_ok": ["1.3.1", "1.3.3"], "control": null}}'::jsonb, '{"expected": {"primary": ["1.3.2"], "also_ok": ["1.3.1", "1.3.3"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
