  ('b78e8b80-fd96-59f7-a0b1-aca1cb785734', 'topic-tag-synthetic-v1', 'topic_tag', 'synthetic', 'cambridge', 'Computer Science 9618', '{"syllabus_code": "9618", "label": "7", "marks_available": 6, "question_text": "Write pseudocode for a function that performs a binary search for a given value in a 1D array of 100 integers sorted in ascending order. The function returns the index of the value, or -1 if it is not found.", "student_answer": "Low <- 1, High <- 100, WHILE Low <= High, Mid <- (Low + High) DIV 2, ... ENDWHILE, RETURN -1", "expected": {"primary": ["19.1.1"], "also_ok": ["10.2.4", "9.2.4", "11.3.4"], "control": null}}'::jsonb, '{"expected": {"primary": ["19.1.1"], "also_ok": ["10.2.4", "9.2.4", "11.3.4"], "control": null}, "draft": true}'::jsonb, true, array[]::text[]),
