-- Syllabus map: the topic_tag stage gets its own eval cases, and a result can carry the stage's
-- structured answer (objective codes and their score; never question or answer text).
--
-- The golden set is generated from evals/golden/topic-tag-v1.json (build_topic_tag_v1.py):
-- original questions written for the eval, no student data, no past-paper or board text. The
-- expected objective codes are DRAFT labels until a person confirms them (needs_human_label).

alter table public.eval_case drop constraint if exists eval_case_stage_check;
alter table public.eval_case add constraint eval_case_stage_check check (stage in ('explain', 'topic_tag'));

alter table public.eval_case_result add column if not exists output jsonb;
comment on column public.eval_case_result.output is
  'Stage-specific structured answer and its score (topic_tag: chosen objective codes, strengths, primary, score). Codes only, never question or answer text.';

on conflict (id) do update set input = excluded.input, draft_labels = excluded.draft_labels, traps = excluded.traps;
